    # occurs least often in the whole grid, avoiding uniform background rows.
    candidates = []
    for r in range(h):
        if all(v == grid[r][0] for v in grid[r]):
            candidates.append((counts[grid[r][0]], "row", r))
    for c in range(w):
        if all(grid[r][c] == grid[0][c] for r in range(h)):
            candidates.append((counts[grid[0][c]], "col", c))

    _, orientation, k = min(candidates)

    if orientation == "row":
        a, b = grid[:k], grid[k + 1:]
        n = min(len(a), len(b))
        a, b = a[:n], b[:n]
    else:
        a = [row[:k] for row in grid]
