        b = [row[:n] for row in b]

    def most_common(panel):
        freq = {}
        for row in panel:
            for v in row:
                freq[v] = freq.get(v, 0) + 1
        return max(freq, key=freq.get)

    bg_a = most_common(a)
    bg_b = most_common(b)

